const SYNCED_PREF_KEYS=[`kinetTheme`,`kinetReduceMotion`,`kinetSoundEnabled`,`kinetSoundVolume`,`kinetViewMode`,`kinetUpcomingView`,`kinetFilmsJournal`,`kinetSeriesSeasonView`,`kinetHeaderOrder`,`kinetWatchRegion`,`kinetSurpriseService`];const PREFS_SYNC_CHECK_MS=4e3;let prefsSyncReady=false;let prefsSynced={};let prefsSyncTimer=null;function readLocalPrefs(){const out={};SYNCED_PREF_KEYS.forEach(k=>{let v=null;try{v=localStorage.getItem(k)}catch(e){}out[k]=v});return out}function changedLocalPrefs(){const local=readLocalPrefs();const changed={};SYNCED_PREF_KEYS.forEach(k=>{if(local[k]!==(prefsSynced[k]??null))changed[k]=local[k]});return changed}function cleanRemotePrefs(settings){const out={};if(!settings||typeof settings!==`object`)return out;SYNCED_PREF_KEYS.forEach(k=>{if(!(k in settings))return;const v=settings[k];if(v===null||typeof v===`string`)out[k]=v});return out}function applyRemotePrefs(remote){const locallyChanged=changedLocalPrefs();let touched=false;Object.keys(remote).forEach(k=>{if(k in locallyChanged)return;const v=remote[k];let cur=null;try{cur=localStorage.getItem(k)}catch(e){}if(cur!==v){try{if(v===null)localStorage.removeItem(k);else localStorage.setItem(k,v)}catch(e){}touched=true}prefsSynced[k]=v});if(touched)refreshUiFromPrefs();return touched}function refreshUiFromPrefs(){if(typeof setTheme===`function`&&typeof getThemeChoice===`function`)setTheme(getThemeChoice());if(typeof setReduceMotion===`function`&&typeof getReduceMotion===`function`)setReduceMotion(getReduceMotion());if(typeof setViewMode===`function`&&typeof getViewMode===`function`)setViewMode(getViewMode());if(typeof applyHeaderNavOrder===`function`)applyHeaderNavOrder();if(typeof syncUpcomingViewButtons===`function`)syncUpcomingViewButtons();if(typeof renderFilmsViewTabs===`function`)renderFilmsViewTabs();if(typeof parseRoute===`function`&&parseRoute().name===`settings`&&typeof openSettingsPage===`function`)openSettingsPage()}async function readRemotePrefs(){const{data,error}=await supabaseClient.from(`user_prefs`).select(`settings`).eq(`user_id`,currentUser.id).maybeSingle();if(error)return{ok:false};return{ok:true,row:!!data,settings:cleanRemotePrefs(data&&data.settings)}}async function pushLocalPrefs(){if(!prefsSyncReady||!currentUser)return;const changed=changedLocalPrefs();if(Object.keys(changed).length===0)return;const remote=await readRemotePrefs();if(!remote.ok)return;applyRemotePrefs(remote.settings);const settings=Object.assign({},remote.settings,changed);const{error}=await supabaseClient.from(`user_prefs`).upsert({user_id:currentUser.id,settings,updated_at:new Date().toISOString()});if(error){console.error(error);return}prefsSynced=Object.assign({},prefsSynced,changed)}async function syncPrefs(){if(!currentUser)return;const remote=await readRemotePrefs();if(!remote.ok){prefsSyncReady=false;return}prefsSyncReady=true;if(Object.keys(remote.settings).length===0){prefsSynced={};await pushLocalPrefs()}else{prefsSynced={};SYNCED_PREF_KEYS.forEach(k=>{prefsSynced[k]=k in remote.settings?remote.settings[k]:null});Object.keys(remote.settings).forEach(k=>{const v=remote.settings[k];try{if(v===null)localStorage.removeItem(k);else localStorage.setItem(k,v)}catch(e){}});refreshUiFromPrefs()}clearInterval(prefsSyncTimer);prefsSyncTimer=setInterval(()=>{pushLocalPrefs().catch(e=>console.error(e))},PREFS_SYNC_CHECK_MS)}document.addEventListener(`visibilitychange`,()=>{if(!prefsSyncReady||!currentUser)return;if(document.visibilityState===`hidden`){pushLocalPrefs().catch(e=>console.error(e));return}readRemotePrefs().then(remote=>{if(remote.ok)applyRemotePrefs(remote.settings)}).catch(e=>console.error(e))});